// Check if the CPU supports VMX by querying CPUID feature flags
bool is_vmx_supported(void) {
    unsigned int eax, ebx, ecx, edx;

    // CPUID leaf 1 returns feature information in ECX
    cpuid(1, &eax, &ebx, &ecx, &edx);

    // The 5th bit of ECX (bit 5) indicates VMX support
    if (ecx & (1 << 5)) {
        return true;
    }
    return false;
}

