func aggregate(urls []string) <-chan string {
	results := make(chan string, 100)
	var wg sync.WaitGroup

	// Fan-out: spawn a goroutine for each URL
	for _, u := range urls {
		wg.Add(1)
		go fetchFeed(u, results, &wg)
	}

	// Wait in background and close channel when all fetchers finish
	go func() {
		wg.Wait()
		close(results)
	}()

	return results
}
